[Form]
public class CELTVendInvoices extends FormRun
{
    // Per-row cache for the newest writeback of the row being rendered: the status columns are
    // display methods that all read the same row, so the first one pays the select and the rest
    // reuse it. Keyed on the journal RecId.
    ClearTaxEInvoiceResponseTable wbCache;
    RecId                         wbCacheJourRecId;
}

/// <summary>
/// All posted vendor invoices, newest first, with the Clear e-invoice status columns.
/// </summary>
public void init()
{
    super();

    VendInvoiceJour_ds.query().dataSourceTable(tableNum(VendInvoiceJour)).addSortField(fieldNum(VendInvoiceJour, InvoiceDate), SortOrder::Descending);
    // Ties on the date need a defined order too: without a second key, same-date invoices
    // come back in whatever order SQL picks, so the grid appeared to shuffle after every
    // re-read (e.g. when Generate e-invoice refreshes the grid).
    VendInvoiceJour_ds.query().dataSourceTable(tableNum(VendInvoiceJour)).addSortField(fieldNum(VendInvoiceJour, InvoiceId), SortOrder::Descending);

    this.applyCountryVisibility();
}

/// <summary>
/// Checkbox-driven visibility (Company capabilities setup): the Self-billing box shows the
/// Generate e-invoice button. France keeps its PPF lifecycle dashboard columns; every other
/// seller country shows the PINT dashboard columns from the UAE ERP dashboard spec (icon,
/// company, voucher, dates, fiscal year, seller name and VAT, self-billing, document id,
/// errors, statuses).
/// </summary>
private void applyCountryVisibility()
{
    boolean franceView = strUpr(new CELTLifecycleActionService().sellerCountryIsoCode()) == CELTConstants::DefaultLifecycleCountry;

    element.design().controlName(formControlStr(CELTVendInvoices, BtnGenerateEInvoice)).visible(CELTLifecycleActionService::isSelfBillingVisible());

    // PINT dashboard columns (every non-France seller country).
    // Icon column hidden everywhere for now (user request) - flip false back to !franceView to re-enable.
    this.toggle(formControlStr(CELTVendInvoices, Grid_Icon), false);
    this.toggle(formControlStr(CELTVendInvoices, Grid_Company), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_AccountingDocNo), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PostingDate), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_DocumentDate), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_FiscalYear), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_SellerName), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_VATNum), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_SelfBilling), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_GovRepStatus), !franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_GovRepReasonMsg), !franceView);

    // France-only columns.
    this.toggle(formControlStr(CELTVendInvoices, Grid_InvoiceDate), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_DueDate), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_InvoiceAccount), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PurchId), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_InvoiceAmount), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_CurrencyCode), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_DocumentStatusReasonCode), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRejectedStatus), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRejectedReasonCode), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRejectedReasonMsg), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRefusedStatus), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRefusedReasonCode), franceView);
    this.toggle(formControlStr(CELTVendInvoices, Grid_PPFLcRefusedReasonMsg), franceView);
}

/// <summary>
/// Shows or hides one design control by name.
/// </summary>
private void toggle(str _controlName, boolean _visible)
{
    element.design().controlName(_controlName).visible(_visible);
}

/// <summary>
/// Traffic-light state for a row, per the UAE dashboard spec: Red when an error is present
/// or any status reads FAILED / REJECTED; Yellow while still in flight (OPEN / PENDING /
/// PROCESSING / NOT_SUBMITTED - including no writeback yet); Green for the rest.
/// </summary>
/// <param name = "_vendJour">the journal row being rendered</param>
/// <returns>the icon column text; the row cell color follows it in displayOption</returns>
public str iconStateOf(VendInvoiceJour _vendJour)
{
    ClearTaxEInvoiceResponseTable wb = this.findWriteback(_vendJour);
    str statuses = strUpr(wb.Success + '|' + wb.STATUS + '|' + wb.PAExchangeStatus + '|' + wb.PPFSubmissionStatus);
    str errorMsg = wb.ErrorDetails != '' ? wb.ErrorDetails : wb.ERROR;

    if (wb.RecId == 0)
    {
        // Nothing sent to Clear yet counts as not submitted.
        return "@CELTLabels:IconYellow";
    }

    if (errorMsg != ''
        || strScan(statuses, 'FAIL', 1, strLen(statuses)) > 0
        || strScan(statuses, 'REJECT', 1, strLen(statuses)) > 0
        || strScan(statuses, 'FALSE', 1, strLen(statuses)) > 0)
    {
        return "@CELTLabels:IconRed";
    }

    if (strScan(statuses, 'OPEN', 1, strLen(statuses)) > 0
        || strScan(statuses, 'PENDING', 1, strLen(statuses)) > 0
        || strScan(statuses, 'PROCESSING', 1, strLen(statuses)) > 0
        || strScan(statuses, 'NOT_SUBMITTED', 1, strLen(statuses)) > 0)
    {
        return "@CELTLabels:IconYellow";
    }

    return "@CELTLabels:IconGreen";
}

/// <summary>
/// The newest Clear writeback row for the vendor invoice, cached per journal row so the
/// grid's status columns cost one select per rendered row instead of one per column.
/// </summary>
/// <param name = "_vendJour">the journal row being rendered</param>
/// <returns>newest writeback row; an empty buffer when none has landed</returns>
public ClearTaxEInvoiceResponseTable findWriteback(VendInvoiceJour _vendJour)
{
    if (wbCacheJourRecId != _vendJour.RecId)
    {
        wbCache.clear();

        if (_vendJour.InvoiceId != '')
        {
            // Match current rows (InvoiceId) and legacy-shaped rows (invoice number in
            // DocumentId), like the response log's filter. Newest by creation time - RecId
            // order is not chronological across AOS sessions (per-AOS id blocks).
            select firstonly wbCache
                order by CreatedDateTime desc, RecId desc
                where wbCache.InvoiceId == _vendJour.InvoiceId
                   || wbCache.DocumentId == _vendJour.InvoiceId;
        }

        wbCacheJourRecId = _vendJour.RecId;
    }

    return wbCache;
}

/// <summary>
/// Forgets the cached writeback row so the next render re-reads it from the table.
/// </summary>
public void invalidateWritebackCache()
{
    wbCacheJourRecId = 0;
}

/// <summary>
/// Re-reads the grid after an action - the sync helper refreshes its caller through this
/// method. The writeback cache must be dropped first, or the re-render of the current row
/// would show the pre-action values.
/// </summary>
/// <param name = "_retainPosition">keep the cursor on the current row</param>
public void research(boolean _retainPosition = true)
{
    this.invalidateWritebackCache();
    VendInvoiceJour_ds.research(_retainPosition);
}

public void executeQuery()
{
    element.invalidateWritebackCache();
    super();
}

public void research(boolean _retainPosition = false)
{
    element.invalidateWritebackCache();
    super(_retainPosition);
}

display str documentId(VendInvoiceJour _vendJour)
{
    // Clear assigns a document id even to a failed submission, and the dashboard shows it
    // whenever one exists (UAE ERP dashboard spec) - the outcome lives in the error and
    // status columns, not in this identifier.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_vendJour);
    return wb.DocumentId != '' ? wb.DocumentId : _vendJour.CELTDocumentId;
}

display str errorDetails(VendInvoiceJour _vendJour)
{
    // France writes the message into ErrorDetails; Clear's MEA (UAE) backend into ERROR.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_vendJour);
    return wb.ErrorDetails != '' ? wb.ErrorDetails : wb.ERROR;
}

/// <summary>
/// Colors the icon cell red / yellow / green to match the icon state (UAE dashboard spec).
/// </summary>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    VendInvoiceJour vendJour = _record as VendInvoiceJour;
    str             state    = element.iconStateOf(vendJour);

    // Excel-style pastel fills; the default text stays readable on all three.
    if (state == "@CELTLabels:IconRed")
    {
        _options.backColor(WinAPI::RGB2int(255, 199, 206));
    }
    else if (state == "@CELTLabels:IconYellow")
    {
        _options.backColor(WinAPI::RGB2int(255, 235, 156));
    }
    else
    {
        _options.backColor(WinAPI::RGB2int(198, 239, 206));
    }

    _options.affectedElementsByControl(element.design().controlName(formControlStr(CELTVendInvoices, Grid_Icon)).id());
    super(_record, _options);
}

display str iconState(VendInvoiceJour _vendJour)
{
    // The cell shows only its color fill (set in displayOption); the state text stays internal.
    return '';
}

display str companyId(VendInvoiceJour _vendJour)
{
    return _vendJour.DataAreaId;
}

display str fiscalYear(VendInvoiceJour _vendJour)
{
    // The writeback carries the fiscal year when the backend sets one; otherwise the
    // invoice date's calendar year stands in.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_vendJour);
    return wb.FiscalYear != '' ? wb.FiscalYear : int2Str(year(_vendJour.InvoiceDate));
}

display str selfBilling(VendInvoiceJour _vendJour)
{
    // Every e-invoice generated from a vendor invoice journal is buyer-issued by
    // definition - the AP generation flow IS the self-billing flow - so this list
    // always shows Yes (UNTDID 1001 type 389 / 261 on the Clear side).
    return enum2Str(NoYes::Yes);
}

display str sellerName(VendInvoiceJour _vendJour)
{
    return VendTable::find(_vendJour.InvoiceAccount).name();
}

display str govReportingStatus(VendInvoiceJour _vendJour)
{
    // Clear's MEA backend reports the government (FTA) reporting outcome in the
    // writeback's PPFSubmissionStatus column.
    return element.findWriteback(_vendJour).PPFSubmissionStatus;
}

display str govReportingReasonMsg(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFSubmissionReasonMsg;
}

display str warningDetails(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).WarningDetails;
}

display str documentStatus(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PAExchangeStatus;
}

display str documentStatusReasonCode(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PAExchangeReasonCodes;
}

display str documentStatusReasonMsg(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PAExchangeReasonMsg;
}

display str ppfLcRejectedStatus(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFLCRejectedStatus;
}

display str ppfLcRejectedReasonCode(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFLCRejectedReasonCodes;
}

display str ppfLcRejectedReasonMsg(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFLCRejectedReasonMsg;
}

display str ppfLcRefusedStatus(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFLCRefusedStatus;
}

display str ppfLcRefusedReasonCode(VendInvoiceJour _vendJour)
{
    return element.findWriteback(_vendJour).PPFLCRefusedReasonCodes;
}

display str ppfLcRefusedReasonMsg(VendInvoiceJour _vendJour)
